import { useEffect, useRef } from 'react';
import { useLatestValue } from '@tui-react/core';
export const useOnCloseEnd = (isMounted, onCloseEndCallback) => {
  const prevIsMounted = useRef(isMounted);
  const onCloseEnd = useLatestValue(onCloseEndCallback);
  useEffect(() => {
    const wasMounted = prevIsMounted.current;
    prevIsMounted.current = isMounted;
    if (wasMounted && !isMounted && onCloseEnd.current) {
      Promise.resolve().then(onCloseEnd.current);
    }
  }, [isMounted, onCloseEnd]);
};